// 传统 API 臃肿的输入

	{

	    "messages": [{"content": "北京有哪些旅游景区", "role": "user"}],

	    "search_source": "baidu_search_v2",

	    "resource_type_filter": [{"type": "web", "top_k": 20}],

	    "search_filter": {

	        "match": {"site": ["www.weather.com.cn"]},

	        "query": {

	            "filter": {"range": {"page_time": {"gte": "now-1w/d","lt": "now/d"}}}

	        }

	    }

	}

